class Solution {
public:
    vector<vector<int>> constructProductMatrix(vector<vector<int>>& grid) {
        int n = grid.size(), m = grid[0].size();
        int mod = 12345;
        vector<vector<int>> p(n, vector<int>(m, 0));
        long long pref = 1;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                p[r][c] = pref;
                pref = (pref * (grid[r][c] % mod)) % mod;
            }
        }
        long long suff = 1;
        for (int r = n - 1; r >= 0; r--) {
            for (int c = m - 1; c >= 0; c--) {
                p[r][c] = (p[r][c] * suff) % mod;
                suff = (suff * (grid[r][c] % mod)) % mod;
            }
        }
        return p;
    }
};

class Solution {
    public int[][] constructProductMatrix(int[][] grid) {
        int n = grid.length, m = grid[0].length;
        int mod = 12345;
        int[][] p = new int[n][m];
        long pref = 1;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                p[r][c] = (int) pref;
                pref = (pref * (grid[r][c] % mod)) % mod;
            }
        }
        long suff = 1;
        for (int r = n - 1; r >= 0; r--) {
            for (int c = m - 1; c >= 0; c--) {
                p[r][c] = (int) ((p[r][c] * suff) % mod);
                suff = (suff * (grid[r][c] % mod)) % mod;
            }
        }
        return p;
    }
}

