var constructProductMatrix = function(grid) {
    const n = grid.length, m = grid[0].length;
    const mod = 12345;
    const p = Array.from({ length: n }, () => new Int32Array(m));
    let pref = 1;
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < m; c++) {
            p[r][c] = pref;
            pref = (pref * (grid[r][c] % mod)) % mod;
        }
    }
    let suff = 1;
    for (let r = n - 1; r >= 0; r--) {
        for (let c = m - 1; c >= 0; c--) {
            p[r][c] = (p[r][c] * suff) % mod;
            suff = (suff * (grid[r][c] % mod)) % mod;
        }
    }
    return p.map(row => Array.from(row));
};
